-- Candidate only: exact-target verification, with authenticated admin claim.
CREATE ROLE nexustalent_verification_writer NOLOGIN NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEROLE NOCREATEDB;
GRANT USAGE ON SCHEMA nexustalent TO nexustalent_verification_writer;
GRANT SELECT, INSERT, UPDATE ON nexustalent.records TO nexustalent_verification_writer;
GRANT EXECUTE ON FUNCTION nexustalent.actor_role() TO nexustalent_verification_writer;
CREATE POLICY verification_read ON nexustalent.records FOR SELECT TO nexustalent_verification_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.verification_action',true) IN ('UPDATE_EMPLOYER_VERIFICATION','UPDATE_INSTITUTION_EMPANELMENT','UPDATE_STUDENT_INSTITUTION_VERIFICATION','UPDATE_STUDENT_PLATFORM_VERIFICATION') AND document_path NOT LIKE '%/%/%' AND ((collection='users' AND document_path='users/'||current_setting('nexustalent.actor_uid',true))
 OR ((collection='employers' AND current_setting('nexustalent.verification_action',true)='UPDATE_EMPLOYER_VERIFICATION' AND document_path='employers/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true')) OR (collection='institutions' AND current_setting('nexustalent.verification_action',true)='UPDATE_INSTITUTION_EMPANELMENT' AND document_path='institutions/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true')) OR (collection='students' AND current_setting('nexustalent.verification_action',true) IN ('UPDATE_STUDENT_INSTITUTION_VERIFICATION','UPDATE_STUDENT_PLATFORM_VERIFICATION') AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR (((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.verification_action',true)='UPDATE_STUDENT_INSTITUTION_VERIFICATION') AND payload->>'institutionId'=current_setting('nexustalent.actor_uid',true)))))
 OR (((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.verification_action',true)='UPDATE_STUDENT_INSTITUTION_VERIFICATION') AND collection='institutions' AND document_path='institutions/'||current_setting('nexustalent.actor_uid',true))
 OR ((((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.verification_action',true)='UPDATE_STUDENT_INSTITUTION_VERIFICATION')) AND collection='auditEvents' AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.verification_action',true),'UTF8')),'hex')
 AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'action'=current_setting('nexustalent.verification_action',true))));
CREATE POLICY verification_update ON nexustalent.records FOR UPDATE TO nexustalent_verification_writer USING (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.verification_action',true) IN ('UPDATE_EMPLOYER_VERIFICATION','UPDATE_INSTITUTION_EMPANELMENT','UPDATE_STUDENT_INSTITUTION_VERIFICATION','UPDATE_STUDENT_PLATFORM_VERIFICATION') AND document_path NOT LIKE '%/%/%' AND ((collection='employers' AND current_setting('nexustalent.verification_action',true)='UPDATE_EMPLOYER_VERIFICATION' AND document_path='employers/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true')) OR (collection='institutions' AND current_setting('nexustalent.verification_action',true)='UPDATE_INSTITUTION_EMPANELMENT' AND document_path='institutions/'||current_setting('nexustalent.target_id',true) AND ((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true')) OR (collection='students' AND current_setting('nexustalent.verification_action',true) IN ('UPDATE_STUDENT_INSTITUTION_VERIFICATION','UPDATE_STUDENT_PLATFORM_VERIFICATION') AND document_path='students/'||current_setting('nexustalent.target_id',true) AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR (((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.verification_action',true)='UPDATE_STUDENT_INSTITUTION_VERIFICATION') AND payload->>'institutionId'=current_setting('nexustalent.actor_uid',true))))) AND payload->>'id'=split_part(document_path,'/',2));
CREATE POLICY verification_audit ON nexustalent.records FOR INSERT TO nexustalent_verification_writer WITH CHECK (
 NULLIF(current_setting('nexustalent.actor_uid',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.target_id',true),'') IS NOT NULL AND NULLIF(current_setting('nexustalent.request_id',true),'') IS NOT NULL AND current_setting('nexustalent.verification_action',true) IN ('UPDATE_EMPLOYER_VERIFICATION','UPDATE_INSTITUTION_EMPANELMENT','UPDATE_STUDENT_INSTITUTION_VERIFICATION','UPDATE_STUDENT_PLATFORM_VERIFICATION') AND document_path NOT LIKE '%/%/%' AND (((SELECT nexustalent.actor_role())='super_admin' AND current_setting('nexustalent.admin_claim',true)='true') OR ((SELECT nexustalent.actor_role())='institution' AND current_setting('nexustalent.verification_action',true)='UPDATE_STUDENT_INSTITUTION_VERIFICATION')) AND collection='auditEvents'
 AND document_path='auditEvents/'||encode(sha256(convert_to(current_setting('nexustalent.request_id',true)||':'||current_setting('nexustalent.actor_uid',true)||':'||current_setting('nexustalent.verification_action',true),'UTF8')),'hex') AND payload->>'eventId'=split_part(document_path,'/',2)
 AND payload->>'actorUid'=current_setting('nexustalent.actor_uid',true) AND payload->>'actorRole'=(SELECT nexustalent.actor_role()) AND payload->>'action'=current_setting('nexustalent.verification_action',true)
 AND payload->>'requestId'=current_setting('nexustalent.request_id',true) AND payload->'immutable'='true'::jsonb AND payload->'ids'=jsonb_build_array(current_setting('nexustalent.target_id',true)));
CREATE FUNCTION nexustalent.guard_verification_update() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE a text:=current_setting('nexustalent.verification_action',true); fields text[];
BEGIN
 IF NOT pg_has_role(current_user,'nexustalent_verification_writer','MEMBER') OR EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) THEN RETURN NEW; END IF;
 IF a='UPDATE_EMPLOYER_VERIFICATION' AND OLD.collection='employers' THEN
  fields:=ARRAY['verificationStatus','verifiedByAdmin','verificationNotes'];
  IF COALESCE(NEW.payload->>'verificationStatus','') NOT IN ('pending','verified','rejected') OR NEW.payload->'verifiedByAdmin' IS DISTINCT FROM to_jsonb(NEW.payload->>'verificationStatus'='verified') THEN RAISE EXCEPTION 'Invalid employer verification' USING ERRCODE='23514'; END IF;
 ELSIF a='UPDATE_INSTITUTION_EMPANELMENT' AND OLD.collection='institutions' THEN
  fields:=ARRAY['empanelmentStatus','verifiedByAdmin','tier','empanelmentNotes'];
  IF COALESCE(NEW.payload->>'empanelmentStatus','') NOT IN ('pending','empanelled','rejected') OR NEW.payload->'verifiedByAdmin' IS DISTINCT FROM to_jsonb(NEW.payload->>'empanelmentStatus'='empanelled') OR COALESCE(NEW.payload->>'tier','') NOT IN ('Tier-1 High Assurance','Tier-2 Verified','Tier-3 Provisional') THEN RAISE EXCEPTION 'Invalid institution empanelment' USING ERRCODE='23514'; END IF;
 ELSIF a='UPDATE_STUDENT_INSTITUTION_VERIFICATION' AND OLD.collection='students' THEN
  fields:=ARRAY['institutionVerificationStatus','verificationNotes'];
  IF COALESCE(NEW.payload->>'institutionVerificationStatus','') NOT IN ('pending','verified','rejected') OR length(trim(COALESCE(NEW.payload->>'verificationNotes',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Verification evidence required' USING ERRCODE='23514'; END IF;
  IF (SELECT nexustalent.actor_role())='institution' AND NOT EXISTS(SELECT 1 FROM nexustalent.records WHERE document_path='institutions/'||current_setting('nexustalent.actor_uid',true) AND payload->>'empanelmentStatus'='empanelled') THEN RAISE EXCEPTION 'Institution authority required' USING ERRCODE='23514'; END IF;
 ELSIF a='UPDATE_STUDENT_PLATFORM_VERIFICATION' AND OLD.collection='students' THEN
  fields:=ARRAY['platformVerificationStatus','verificationNotes'];
  IF COALESCE(NEW.payload->>'platformVerificationStatus','') NOT IN ('pending','verified','rejected') THEN RAISE EXCEPTION 'Invalid platform verification' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'Invalid verification target' USING ERRCODE='23514'; END IF;
 IF (NEW.payload-fields) IS DISTINCT FROM (OLD.payload-fields) THEN RAISE EXCEPTION 'Unrelated profile modification' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END
$$;
CREATE TRIGGER verification_update_guard BEFORE UPDATE ON nexustalent.records FOR EACH ROW EXECUTE FUNCTION nexustalent.guard_verification_update();
REVOKE ALL ON FUNCTION nexustalent.guard_verification_update() FROM PUBLIC;
